from cofabriq.issues import vectors
from cofabriq.issues.vectors import clean_issue_text
from tests.test_dedupe import issue

VSCODE_REPORT = """Type: <b>Bug</b>

<!-- Please read our Rules of Conduct: https://example.com/codeofconduct/ -->
<!-- generated by issue reporter -->
The terminal freezes when I paste a long line.

VS Code version: Code 1.86.2 (Universal)
<details>
<summary>System Info</summary>

|Item|Value|
|---|---|
|Screen Reader|no|
|VM|0%|
</details><details>
<summary>A/B Experiments</summary>

```
vspor708:30202333
vspor879:30202332
```

</details>
<details><summary>Extensions (2)</summary>

Extension|Author (truncated)|Version
---|---|---
vscode-eslint|dba|2.4.4
</details>
"""

OPEN_WEBUI_REPORT = """### Check Existing Issues

- [x] I have searched the existing issues and discussions.
- [x] I am using the latest version of Open WebUI.

### Installation Method

Git Clone

### Ollama Version (if applicable)

_No response_

### Confirmation

- [x] I have read and followed all instructions in `README.md`.
- [x] I have documented **step-by-step reproduction instructions**. My steps:
- Start with the initial platform/version/OS and dependencies used,
- Specify exact install/launch/configure commands,

### Actual Behavior

Chats with OpenAI models fail after upgrading.

<img width="1011" alt="Image" src="https://github.com/user-attachments/assets/dec8" />
"""


def test_template_comments_and_reporter_blocks_go_and_the_report_stays() -> None:
    cleaned = clean_issue_text(VSCODE_REPORT)

    assert cleaned == (
        "Type: <b>Bug</b>\n\n"
        "The terminal freezes when I paste a long line.\n\n"
        "VS Code version: Code 1.86.2 (Universal)"
    )


def test_checkboxes_headers_empty_answers_and_screenshots_go() -> None:
    cleaned = clean_issue_text(OPEN_WEBUI_REPORT)

    assert cleaned == ("Git Clone\n\nChats with OpenAI models fail after upgrading.")


def test_a_developers_own_details_block_stays() -> None:
    body = "<details><summary>User Settings</summary>\n\nfoo: bar\n</details>"

    assert "foo: bar" in clean_issue_text(body)


def test_a_long_fence_keeps_its_head_and_its_tail() -> None:
    log = "\n".join(f"line {i} ok" for i in range(500))
    body = f"It crashes:\n```\n{log}\nTypeError: x is not a function\n```\nSee above."

    cleaned = clean_issue_text(body)

    assert "line 0 ok" in cleaned
    assert "TypeError: x is not a function" in cleaned
    assert "line 250 ok" not in cleaned
    assert cleaned.startswith("It crashes:") and cleaned.endswith("See above.")
    assert len(cleaned) < 1000


def test_a_short_fence_is_untouched() -> None:
    body = "Run:\n```sh\n# install\nnpm i\n```"

    assert clean_issue_text(body) == body


def test_a_shell_comment_in_a_fence_is_not_taken_for_a_header() -> None:
    assert "# install deps" in clean_issue_text("```sh\n# install deps\n```")


def test_a_long_heading_with_the_error_in_it_stays() -> None:
    body = "### TypeError: cannot read properties of undefined (reading 'map')"

    assert "TypeError" in clean_issue_text(body)


def test_links_and_alt_text_survive_but_attachments_and_tokens_do_not() -> None:
    token = "a1B2" * 20
    body = (
        "See https://github.com/acme/app/issues/3 and ![crash dialog](x.png).\n"
        "https://github.com/user-attachments/files/1/log.zip\n"
        f"key {token} end"
    )

    cleaned = clean_issue_text(body)

    assert "https://github.com/acme/app/issues/3" in cleaned
    assert "crash dialog" in cleaned
    assert "user-attachments" not in cleaned
    assert token not in cleaned


def test_ansi_escapes_and_windows_line_endings_go() -> None:
    assert clean_issue_text("\x1b[31merror\x1b[0m\r\nnext") == "error\nnext"


def test_embed_input_is_the_title_and_the_cleaned_body() -> None:
    item = issue(1, title="Freeze on paste", body=VSCODE_REPORT)

    text = vectors.issue_input(item)

    assert text.startswith("Freeze on paste\n\nType: <b>Bug</b>")
    assert "System Info" not in text and "bug_report" not in text


def test_a_body_with_nothing_but_template_embeds_the_title_alone() -> None:
    item = issue(1, title="Crash", body="<!-- fill this in -->\n![shot](a.png)")

    assert vectors.issue_input(item) == "Crash\n\nshot"
    assert vectors.issue_input(issue(2, title="Crash", body="<!-- x -->")) == "Crash"


def test_the_cap_counts_cleaned_characters() -> None:
    boilerplate = "<!-- " + "x" * 8000 + " -->\n"
    item = issue(1, title="t", body=boilerplate + "real " * 100)

    assert vectors.issue_input(item).endswith("real")
